 private void chatRow(JSONObject c){if(c==null)return;LinearLayout r=new LinearLayout(this);TextView t=tv(c.optString("title","New chat"),16);Button d=btn("Excluir");r.setBackgroundColor(card);r.addView(t,new LinearLayout.LayoutParams(0,-2,1));r.addView(d);add(r);r.setOnClickListener(v->{chatId=c.optString("id");currentChat=c;providerId=c.optString("providerId",providerId);openChat(c);});d.setOnClickListener(v->confirm("Excluir conversa?","Esta ação não pode ser desfeita.",()->run(()->api.call("DELETE","/chats/"+c.optString("id"),null),x->loadProfile(true),this::error)));}
