 private void renderChat(JSONObject c){JSONArray ms=arr(c,"messages");if(ms.length()==0)add(tv("Comece quando quiser.",15));for(int i=0;i<ms.length();i++){JSONObject m=ms.optJSONObject(i);if(m==null)continue;TextView v=tv(("user".equals(m.optString("role"))?"Você\n":"Aether\n")+m.optString("content"),16);v.setBackgroundColor("user".equals(m.optString("role"))?Color.rgb(28,57,52):card);add(v);toolCards(m);gap();}EditText compose=input("Mensagem",false);compose.setSingleLine(false);compose.setMinLines(2);add(compose);Button send=btn("Enviar");add(send);send.setOnClickListener(v->{if(sending)return;String q=compose.getText().toString().trim();if(q.length()==0)return;send.setEnabled(false);send(q,compose,send);});}
