 private void providerForm(JSONObject old){shell("Provedor","Formato: openai ou anthropic");EditText n=input("Nome",false),u=input("Base URL HTTPS",false),m=input("Modelo",false),f=input("Formato (openai/anthropic)",false),k=input("Chave API (obrigatória ao salvar)",true);if(old!=null){n.setText(old.optString("name"));u.setText(old.optString("baseUrl"));m.setText(old.optString("model"));f.setText(old.optString("format","openai"));}else f.setText("openai");add(n);add(u);add(m);add(f);add(k);Button save=btn("Salvar provedor");add(save);save.setOnClickListener(v->{if(old!=null&&k.getText().toString().trim().isEmpty()){toast("A API atual não permite editar sem reenviar a chave.");return;}run(()->api.call("POST","/providers",new JSONObject().put("id",old==null?"":old.optString("id")).put("name",n.getText().toString()).put("baseUrl",u.getText().toString()).put("model",m.getText().toString()).put("format",f.getText().toString()).put("apiKey",k.getText().toString())),x->loadProfileThenProviders(),this::error);});if(old!=null){Button del=btn("Excluir provedor");add(del);del.setOnClickListener(v->confirm("Excluir provedor?","Chats que usam este provedor precisarão de outro.",()->run(()->api.call("DELETE","/providers/"+old.optString("id"),null),x->loadProfileThenProviders(),this::error)));}}
