 private void confirm(String a,String b,Runnable yes){new AlertDialog.Builder(this).setTitle(a).setMessage(b).setNegativeButton("Cancelar",null).setPositiveButton("Confirmar",(d,w)->yes.run()).show();} private String jsonText(Object v){return v instanceof JSONObject||v instanceof JSONArray?v.toString():String.valueOf(v);} interface Work{JSONObject go()throws Exception;}interface Ok{void yes(JSONObject r);}interface Bad{void no(String e);}private void run(Work w,Ok ok,Bad bad){io.execute(()->{try{JSONObject r=w.go();runOnUiThread(()->ok.yes(r));}catch(Exception e){runOnUiThread(()->bad.no(e.getMessage()==null?"Não foi possível concluir.":e.getMessage()));}});}private void error(String e){toast(e);}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}

